(* [comment removed for export] *)
Definition put_head_post (sp gp tp s7 s8 s9 s10 s11 s6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo U size TH qcache : Z) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a5 a6 a7 t3 t4 t5 t6 : word) m',
    ms' = MS (mkR (wz 0x53358) (Z_to_bv 64 (bv_unsigned sp + -2208)) gp tp t0 t1 t2 (wz (AINST + OI_Q)) (wz (TH + OT_TQ))
                  (wz (TH + OT_TQ)) (wz (TH + OT_CACHE)) (Z_to_bv 64 (bv_unsigned sp + -2128)) (wz (U + -16)) (wz size) a5 a6 a7
                  (wz size) (Z_to_bv 64 (bv_unsigned sp + -2128)) (wz (TH + OT_CACHE)) (wz (U + -16)) (wz qcache) s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x53364) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp + -2128); (sh U, sh U + nsh size)] m m'
    /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp + -2208)
    /\ rw_cells asegs m' (bv_unsigned sp + -2208) (put_frame sp s6 U TH)
    /\ u8arr asegs m' (sh U) (repeat (b8 kAsanHeapFreeMagic) (Z.to_nat (nsh size))).

